def count_fires(spec: str, blackouts: list[tuple[int, int]], a: int, b: int) -> int:
    # Parse spec
    fields = spec.split()
    if len(fields) != 3:
        raise ValueError("Expected exactly 3 fields")

    def parse_field(field: str, max_val: int) -> set:
        result = set()
        terms = field.split(',')
        for term in terms:
            if term == '':
                raise ValueError("Empty term")
            # Split by /
            if term.count('/') > 1:
                raise ValueError("More than one /")
            if '/' in term:
                base, step_str = term.split('/')
                if not step_str or not step_str.isdigit():
                    raise ValueError("Invalid step")
                step = int(step_str)
                if step == 0:
                    raise ValueError("Step of 0")
            else:
                base = term
                step = 1

            if base == '*':
                start, end = 0, max_val
            elif '-' in base:
                parts = base.split('-')
                if len(parts) != 2:
                    raise ValueError("Invalid range")
                if not parts[0].isdigit() or not parts[1].isdigit():
                    raise ValueError("Invalid range values")
                start, end = int(parts[0]), int(parts[1])
                if start > end:
                    raise ValueError("N > M")
                if start > max_val or end > max_val:
                    raise ValueError("Value above MAX")
            else:
                if not base.isdigit():
                    raise ValueError("Invalid value")
                start = int(base)
                end = max_val
                if start > max_val:
                    raise ValueError("Value above MAX")

            for v in range(start, end + 1, step):
                result.add(v)

        return result

    minute_set = parse_field(fields[0], 59)
    hour_set = parse_field(fields[1], 23)
    weekday_set = parse_field(fields[2], 6)

    W = 10080  # minutes in a week

    # Precompute which minutes in one week the alarm fires
    fires = [0] * W
    for t in range(W):
        if (t % 60) in minute_set and (t // 60) % 24 in hour_set and (t // 1440) % 7 in weekday_set:
            fires[t] = 1

    total_per_week = sum(fires)

    # Prefix sum for O(1) range counting within a week
    prefix = [0] * (W + 1)
    for i in range(W):
        prefix[i + 1] = prefix[i] + fires[i]

    def count_up_to(n: int) -> int:
        """Number of fires in [0, n)."""
        if n <= 0:
            return 0
        full_weeks = n // W
        rem = n % W
        return full_weeks * total_per_week + prefix[rem]

    def count_in_range(lo: int, hi: int) -> int:
        """Number of fires in [lo, hi)."""
        if hi <= lo:
            return 0
        return count_up_to(hi) - count_up_to(lo)

    if b <= a:
        return 0

    total_fires = count_in_range(a, b)

    if not blackouts:
        return total_fires

    # Intersect blackouts with [a, b), then merge
    intervals = []
    for s, e in blackouts:
        s2 = max(s, a)
        e2 = min(e, b)
        if s2 < e2:
            intervals.append((s2, e2))

    if not intervals:
        return total_fires

    intervals.sort()
    merged = [list(intervals[0])]
    for s, e in intervals[1:]:
        if s <= merged[-1][1]:
            if e > merged[-1][1]:
                merged[-1][1] = e
        else:
            merged.append([s, e])

    blackout_fires = 0
    for s, e in merged:
        blackout_fires += count_in_range(s, e)

    return total_fires - blackout_fires
