class FairQueue:
    """A job queue with priority aging, pausing, re-queueing, and cancellation."""

    WAITING = "WAITING"
    PAUSED = "PAUSED"
    RUNNING = "RUNNING"

    def __init__(self, aging: int, cap: int):
        assert aging >= 1
        assert cap >= 0
        self._aging = aging
        self._cap = cap
        self._jobs: dict[str, dict] = {}
        self._seq = 0

    # ---- internal helpers ----

    def _waited(self, job: dict, t: int) -> int:
        """Accumulated waiting time up to time t."""
        if job["state"] == self.WAITING:
            return job["waited"] + (t - job["wait_start"])
        return job["waited"]

    def _eff_prio(self, job: dict, t: int) -> int:
        return job["base"] + min(self._cap, self._waited(job, t) // self._aging)

    def _sort_key(self, job: dict, t: int):
        return (-self._eff_prio(job, t), -self._waited(job, t), job["seq"])

    def _waiting_list(self) -> list[tuple[str, dict]]:
        return [(n, j) for n, j in self._jobs.items() if j["state"] == self.WAITING]

    # ---- public API ----

    def submit(self, job: str, priority: int, t: int) -> None:
        if job in self._jobs:
            raise ValueError(f"Job '{job}' already exists")
        self._jobs[job] = {
            "base": priority,
            "state": self.WAITING,
            "waited": 0,
            "wait_start": t,
            "seq": self._seq,
        }
        self._seq += 1

    def start(self, t: int) -> str | None:
        candidates = self._waiting_list()
        if not candidates:
            return None
        candidates.sort(key=lambda x: self._sort_key(x[1], t))
        name, job = candidates[0]
        job["waited"] += t - job["wait_start"]
        job["state"] = self.RUNNING
        job["wait_start"] = None
        return name

    def finish(self, job: str, t: int) -> None:
        if job not in self._jobs or self._jobs[job]["state"] != self.RUNNING:
            raise KeyError(job)
        del self._jobs[job]

    def requeue(self, job: str, t: int) -> None:
        if job not in self._jobs or self._jobs[job]["state"] != self.RUNNING:
            raise KeyError(job)
        j = self._jobs[job]
        j["base"] -= 1
        j["state"] = self.WAITING
        j["wait_start"] = t
        j["seq"] = self._seq
        self._seq += 1

    def pause(self, job: str, t: int) -> bool:
        if job not in self._jobs:
            raise KeyError(job)
        j = self._jobs[job]
        if j["state"] == self.WAITING:
            j["waited"] += t - j["wait_start"]
            j["state"] = self.PAUSED
            j["wait_start"] = None
            return True
        elif j["state"] == self.PAUSED:
            return False
        else:
            raise KeyError(job)

    def resume(self, job: str, t: int) -> bool:
        if job not in self._jobs:
            raise KeyError(job)
        j = self._jobs[job]
        if j["state"] == self.PAUSED:
            j["state"] = self.WAITING
            j["wait_start"] = t
            return True
        elif j["state"] == self.WAITING:
            return False
        else:
            raise KeyError(job)

    def cancel(self, job: str) -> bool:
        if job in self._jobs:
            del self._jobs[job]
            return True
        return False

    def queue(self, t: int) -> list[tuple[str, int]]:
        candidates = self._waiting_list()
        candidates.sort(key=lambda x: self._sort_key(x[1], t))
        return [(name, self._eff_prio(j, t)) for name, j in candidates]
