def match_route(pattern: str, path: str) -> dict:
    import re

    if not pattern.startswith('/'):
        raise ValueError("pattern must start with '/'")
    if not path.startswith('/'):
        raise ValueError("path must start with '/'")

    pat_segs = pattern[1:].split('/')
    path_segs = path[1:].split('/')

    name_re = re.compile(r'^[A-Za-z0-9_]+$')
    parsed = []
    seen_names = set()

    for seg in pat_segs:
        if seg.startswith(':'):
            if seg.endswith('?') and len(seg) > 2:
                name = seg[1:-1]
                if not name_re.match(name):
                    raise ValueError(f"Invalid name in pattern: {seg}")
                if name in seen_names:
                    raise ValueError(f"Duplicate name in pattern: {name}")
                seen_names.add(name)
                parsed.append(('opt', name))
            elif len(seg) > 1:
                name = seg[1:]
                if not name_re.match(name):
                    raise ValueError(f"Invalid name in pattern: {seg}")
                if name in seen_names:
                    raise ValueError(f"Duplicate name in pattern: {name}")
                seen_names.add(name)
                parsed.append(('param', name))
            else:
                raise ValueError(f"Invalid pattern segment: {seg}")
        elif seg.startswith('#'):
            if len(seg) > 1:
                name = seg[1:]
                if not name_re.match(name):
                    raise ValueError(f"Invalid name in pattern: {seg}")
                if name in seen_names:
                    raise ValueError(f"Duplicate name in pattern: {name}")
                seen_names.add(name)
                parsed.append(('int', name))
            else:
                raise ValueError(f"Invalid pattern segment: {seg}")
        elif seg.startswith('*'):
            if len(seg) > 1:
                name = seg[1:]
                if not name_re.match(name):
                    raise ValueError(f"Invalid name in pattern: {seg}")
                if name in seen_names:
                    raise ValueError(f"Duplicate name in pattern: {name}")
                seen_names.add(name)
                parsed.append(('star', name))
            else:
                raise ValueError(f"Invalid pattern segment: {seg}")
        else:
            parsed.append(('lit', seg))

    def is_digits(s):
        if not s:
            return False
        for c in s:
            if c < '0' or c > '9':
                return False
        return True

    n = len(parsed)
    m = len(path_segs)

    # dp[i][j] = True if parsed[i:] can match path_segs[j:]
    dp = [[False] * (m + 1) for _ in range(n + 1)]
    dp[n][m] = True

    for i in range(n - 1, -1, -1):
        ptype, pname = parsed[i]
        if ptype == 'lit':
            for j in range(m):
                dp[i][j] = (path_segs[j] == pname) and dp[i + 1][j + 1]
        elif ptype == 'param':
            for j in range(m):
                dp[i][j] = (path_segs[j] != '') and dp[i + 1][j + 1]
        elif ptype == 'int':
            for j in range(m):
                dp[i][j] = is_digits(path_segs[j]) and dp[i + 1][j + 1]
        elif ptype == 'opt':
            for j in range(m + 1):
                if dp[i + 1][j]:
                    dp[i][j] = True
                elif j < m and path_segs[j] != '' and dp[i + 1][j + 1]:
                    dp[i][j] = True
        elif ptype == 'star':
            # dp[i][j] = exists j' >= j such that dp[i+1][j'] is True
            # Use suffix OR for O(1) per cell
            suffix_or = [False] * (m + 1)
            suffix_or[m] = dp[i + 1][m]
            for j in range(m - 1, -1, -1):
                suffix_or[j] = dp[i + 1][j] or suffix_or[j + 1]
            for j in range(m + 1):
                dp[i][j] = suffix_or[j]

    if not dp[0][0]:
        return None

    # Trace the optimal path (fewest segments for each flexible segment, in order)
    result = {}
    i = 0
    j = 0
    while i < n:
        ptype, pname = parsed[i]
        if ptype == 'lit':
            i += 1
            j += 1
        elif ptype == 'param':
            result[pname] = path_segs[j]
            i += 1
            j += 1
        elif ptype == 'int':
            result[pname] = int(path_segs[j])
            i += 1
            j += 1
        elif ptype == 'opt':
            if dp[i + 1][j]:
                # Prefer matching 0 segments
                result[pname] = None
                i += 1
            else:
                result[pname] = path_segs[j]
                i += 1
                j += 1
        elif ptype == 'star':
            # Find smallest j' >= j with dp[i+1][j'] == True
            j_prime = j
            while j_prime <= m and not dp[i + 1][j_prime]:
                j_prime += 1
            result[pname] = path_segs[j:j_prime]
            i += 1
            j = j_prime

    return result
