import heapq


def ferry_plan(routes: list[tuple[str, str, int, int, int]], src: str, dst: str, t0: int):
    if src == dst:
        return (t0, 0)

    # Build adjacency list, skipping useless a == b routes
    adj = {}
    for a, b, first, every, duration in routes:
        if a == b:
            continue
        if a not in adj:
            adj[a] = []
        adj[a].append((b, first, every, duration))

    def next_departure(t, first, every):
        """Return the earliest ferry departure time >= t for a schedule."""
        if t <= first:
            return first
        return first + ((t - first + every - 1) // every) * every

    # Step 1: Dijkstra to find the earliest arrival time at every port
    INF = float('inf')
    earliest = {src: t0}
    pq = [(t0, src)]

    while pq:
        t, p = heapq.heappop(pq)
        if t > earliest.get(p, INF):
            continue
        for (q, first, every, duration) in adj.get(p, []):
            arrive = next_departure(t, first, every) + duration
            if arrive < earliest.get(q, INF):
                earliest[q] = arrive
                heapq.heappush(pq, (arrive, q))

    if dst not in earliest:
        return None

    T_star = earliest[dst]

    # Step 2: BFS by number of ferries to find the minimum number of ferries
    # that arrive at dst at exactly T_star.
    # At each level k, we track the earliest arrival at each port using exactly k ferries.
    # Arriving earlier at a port is always at least as good (we can always wait),
    # so keeping only the earliest time per port is sufficient.
    current = {src: t0}  # port -> earliest arrival with k ferries

    for k in range(0, 60):  # at most 59 ferries (60 ports, no useful revisits)
        if dst in current and current[dst] <= T_star:
            return (T_star, k)

        # Expand: take one more ferry
        next_dist = {}
        for p, t in current.items():
            if t > T_star:
                continue
            for (q, first, every, duration) in adj.get(p, []):
                arrive = next_departure(t, first, every) + duration
                if arrive <= T_star:
                    if q not in next_dist or arrive < next_dist[q]:
                        next_dist[q] = arrive

        current = next_dist
        if not current:
            break

    return None
