def run_script(source: str, max_steps: int) -> tuple[list[int], str]:
    lines = source.split("\n")

    def is_operand(tok: str) -> bool:
        if not tok:
            return False
        if tok[0] == '-':
            return len(tok) > 1 and tok[1:].isdigit()
        if tok[0].isdigit():
            return tok.isdigit()
        return all(c in 'abcdefghijklmnopqrstuvwxyz' for c in tok)

    OPERATORS = frozenset(('+', '-', '*', '/', '%', '<', '>', '='))

    def validate_expr(tokens: list[str]) -> None:
        if not tokens:
            raise ValueError("empty expression")
        if len(tokens) % 2 == 0:
            raise ValueError("wrong alternation in expression")
        for i, tok in enumerate(tokens):
            if i % 2 == 0:
                if not is_operand(tok):
                    raise ValueError(f"bad operand: {tok}")
            else:
                if tok not in OPERATORS:
                    raise ValueError(f"bad operator: {tok}")

    # --- Static parse & check ---
    instructions: list[list] = []
    block_stack: list[list] = []  # [type, instr_idx, else_idx, has_else]
    while_end_map: dict[int, int] = {}
    pending_breaks: list[tuple[int, int]] = []
    pending_skips: list[tuple[int, int]] = []

    for line in lines:
        tokens = line.split()
        if not tokens or tokens[0].startswith('#'):
            continue

        first = tokens[0]

        if first == 'set':
            if len(tokens) < 4:
                raise ValueError("malformed set")
            name = tokens[1]
            if not name or not all(c in 'abcdefghijklmnopqrstuvwxyz' for c in name):
                raise ValueError("malformed set: bad name")
            if tokens[2] != '=':
                raise ValueError("malformed set: expected =")
            validate_expr(tokens[3:])
            instructions.append(['SET', name, tokens[3:]])

        elif first == 'emit':
            if len(tokens) < 2:
                raise ValueError("malformed emit: no expression")
            validate_expr(tokens[1:])
            instructions.append(['EMIT', tokens[1:]])

        elif first == 'if':
            if len(tokens) < 2:
                raise ValueError("malformed if: no expression")
            validate_expr(tokens[1:])
            idx = len(instructions)
            block_stack.append(['if', idx, -1, False])
            instructions.append(['IF', tokens[1:], -1])  # jump_false to resolve

        elif first == 'while':
            if len(tokens) < 2:
                raise ValueError("malformed while: no expression")
            validate_expr(tokens[1:])
            idx = len(instructions)
            block_stack.append(['while', idx, -1, False])
            instructions.append(['WHILE', tokens[1:], -1])  # jump_false to resolve

        elif first == 'else':
            if len(tokens) != 1:
                raise ValueError("extra tokens after else")
            if not block_stack or block_stack[-1][0] != 'if' or block_stack[-1][3]:
                raise ValueError("else without matching if")
            else_idx = len(instructions)
            block_stack[-1][2] = else_idx
            block_stack[-1][3] = True
            instructions[block_stack[-1][1]][2] = else_idx
            instructions.append(['ELSE', -1])  # jump_end to resolve

        elif first == 'end':
            if len(tokens) != 1:
                raise ValueError("extra tokens after end")
            if not block_stack:
                raise ValueError("end with no open block")
            btype, instr_idx, else_idx, has_else = block_stack.pop()
            end_idx = len(instructions)
            if btype == 'if':
                if not has_else:
                    instructions[instr_idx][2] = end_idx
                else:
                    instructions[else_idx][1] = end_idx
                instructions.append(['END', 'if', -1])
            else:
                instructions[instr_idx][2] = end_idx + 1
                while_end_map[instr_idx] = end_idx
                instructions.append(['END', 'while', instr_idx])

        elif first == 'break':
            if len(tokens) != 1:
                raise ValueError("extra tokens after break")
            while_idx = None
            for i in range(len(block_stack) - 1, -1, -1):
                if block_stack[i][0] == 'while':
                    while_idx = block_stack[i][1]
                    break
            if while_idx is None:
                raise ValueError("break outside while")
            idx = len(instructions)
            pending_breaks.append((idx, while_idx))
            instructions.append(['BREAK', -1])

        elif first == 'skip':
            if len(tokens) != 1:
                raise ValueError("extra tokens after skip")
            while_idx = None
            for i in range(len(block_stack) - 1, -1, -1):
                if block_stack[i][0] == 'while':
                    while_idx = block_stack[i][1]
                    break
            if while_idx is None:
                raise ValueError("skip outside while")
            idx = len(instructions)
            pending_skips.append((idx, while_idx))
            instructions.append(['SKIP', -1])

        elif first == 'halt':
            if len(tokens) != 1:
                raise ValueError("extra tokens after halt")
            instructions.append(['HALT'])

        else:
            raise ValueError(f"unknown first token: {first}")

    if block_stack:
        raise ValueError("block still open at end")

    # Resolve deferred jumps
    for idx, widx in pending_breaks:
        instructions[idx][1] = while_end_map[widx] + 1
    for idx, widx in pending_skips:
        instructions[idx][1] = widx

    # --- Execution ---
    variables: dict[str, int] = {}
    emitted: list[int] = []
    steps = 0
    pc = 0
    n = len(instructions)

    def get_operand(tok: str) -> int:
        if tok[0] == '-':
            return -int(tok[1:])
        if tok[0].isdigit():
            return int(tok)
        return variables.get(tok, 0)

    def eval_expr(tokens: list[str]) -> int:
        result = get_operand(tokens[0])
        i = 1
        while i < len(tokens):
            op = tokens[i]
            b = get_operand(tokens[i + 1])
            if op == '+':
                result = result + b
            elif op == '-':
                result = result - b
            elif op == '*':
                result = result * b
            elif op == '/':
                if b == 0:
                    raise ZeroDivisionError
                result = result // b
            elif op == '%':
                if b == 0:
                    raise ZeroDivisionError
                result = result % b
            elif op == '<':
                result = 1 if result < b else 0
            elif op == '>':
                result = 1 if result > b else 0
            elif op == '=':
                result = 1 if result == b else 0
            i += 2
        return result

    while pc < n:
        instr = instructions[pc]
        itype = instr[0]

        if itype == 'SET':
            if steps >= max_steps:
                return (emitted, "limit")
            try:
                val = eval_expr(instr[2])
            except ZeroDivisionError:
                return (emitted, "error")
            variables[instr[1]] = val
            steps += 1
            pc += 1

        elif itype == 'EMIT':
            if steps >= max_steps:
                return (emitted, "limit")
            try:
                val = eval_expr(instr[1])
            except ZeroDivisionError:
                return (emitted, "error")
            emitted.append(val)
            steps += 1
            pc += 1

        elif itype == 'IF':
            if steps >= max_steps:
                return (emitted, "limit")
            try:
                val = eval_expr(instr[1])
            except ZeroDivisionError:
                return (emitted, "error")
            steps += 1
            if val != 0:
                pc += 1
            else:
                pc = instr[2]

        elif itype == 'ELSE':
            pc = instr[1]

        elif itype == 'WHILE':
            if steps >= max_steps:
                return (emitted, "limit")
            try:
                val = eval_expr(instr[1])
            except ZeroDivisionError:
                return (emitted, "error")
            steps += 1
            if val != 0:
                pc += 1
            else:
                pc = instr[2]

        elif itype == 'END':
            if instr[1] == 'while':
                pc = instr[2]
            else:
                pc += 1

        elif itype == 'BREAK':
            if steps >= max_steps:
                return (emitted, "limit")
            steps += 1
            pc = instr[1]

        elif itype == 'SKIP':
            if steps >= max_steps:
                return (emitted, "limit")
            steps += 1
            pc = instr[1]

        elif itype == 'HALT':
            if steps >= max_steps:
                return (emitted, "limit")
            steps += 1
            return (emitted, "halt")

    return (emitted, "done")
