def eval_tally(src: str, env: dict) -> int:
    n = len(src)

    # Tokenize
    tokens = []
    i = 0
    two_char_ops = {'<=', '>=', '==', '!='}
    one_char_ops = set('+-*/%^()<>?:!&|')

    while i < n:
        if src[i] == ' ':
            i += 1
            continue
        if i + 1 < n and src[i:i+2] in two_char_ops:
            tokens.append(('op', src[i:i+2], i))
            i += 2
            continue
        if '0' <= src[i] <= '9':
            j = i
            while j < n and '0' <= src[j] <= '9':
                j += 1
            tokens.append(('int', int(src[i:j]), i))
            i = j
            continue
        if (src[i].isalpha() or src[i] == '_'):
            j = i
            while j < n and (src[j].isalpha() or '0' <= src[j] <= '9' or src[j] == '_'):
                j += 1
            tokens.append(('name', src[i:j], i))
            i = j
            continue
        if src[i] in one_char_ops:
            tokens.append(('op', src[i], i))
            i += 1
            continue
        tokens.append(('illegal', src[i], i))
        i += 1

    # Parser (recursive descent)
    tp = [0]

    def peek():
        if tp[0] < len(tokens):
            return tokens[tp[0]]
        return None

    def advance():
        tok = tokens[tp[0]]
        tp[0] += 1
        return tok

    def parse_expr():
        left = parse_or()
        if peek() is not None and peek()[0] == 'op' and peek()[1] == '?':
            advance()
            a = parse_expr()
            tok = peek()
            if tok is None or tok[0] != 'op' or tok[1] != ':':
                if tok is None:
                    raise ValueError("syntax", n)
                raise ValueError("syntax", tok[2])
            advance()
            b = parse_expr()
            return ('cond', left, a, b)
